import React, { useState, useEffect } from 'react';
import { Check, X, Crown, ShieldCheck, Zap, Rocket, CreditCard, Loader2, QrCode, ArrowLeft, Lock, AlertCircle, Shield } from 'lucide-react';
import { User } from '../types';

declare global {
  interface Window {
    Stripe: any;
  }
}

interface SubscriptionModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentUser: User;
  onUpgrade: (plan: 'silver' | 'bronze' | 'gold') => Promise<void>;
  onCancelPlan: () => Promise<void>;
}

export const SubscriptionModal: React.FC<SubscriptionModalProps> = ({ isOpen, onClose, currentUser, onUpgrade, onCancelPlan }) => {
  const [viewState, setViewState] = useState<'plans' | 'payment' | 'cancel_confirmation'>('plans');
  const [selectedPlanId, setSelectedPlanId] = useState<'silver' | 'bronze' | 'gold' | null>(null);
  const [processingMethod, setProcessingMethod] = useState<'pix' | 'card' | 'stripe' | null>(null);
  const [isCancelling, setIsCancelling] = useState(false);
  const [stripe, setStripe] = useState<any>(null);

  useEffect(() => {
    // Initialize Stripe when modal opens
    if (isOpen && !stripe && window.Stripe) {
      // Usando uma chave de teste pública fictícia
      setStripe(window.Stripe('pk_test_51PqLuckFlowKeyPlaceholder'));
    }
  }, [isOpen, stripe]);

  if (!isOpen) return null;

  const PLANS = [
      {
          id: 'silver',
          label: 'Prata',
          price: 'R$ 25,00',
          priceId: 'price_silver_123',
          period: '/mês',
          icon: ShieldCheck,
          color: 'text-gray-400',
          borderColor: 'border-gray-400/30',
          bgGradient: 'from-gray-500/10 to-transparent',
          highlight: false,
          features: [
              'Até 5 Projetos',
              'Gestão básica de tarefas',
              'Anexos limitados (100MB)',
              'Suporte por email'
          ]
      },
      {
          id: 'bronze',
          label: 'Bronze',
          price: 'R$ 32,90',
          priceId: 'price_bronze_456',
          period: '/mês',
          icon: Zap,
          color: 'text-amber-700',
          borderColor: 'border-amber-700/30',
          bgGradient: 'from-amber-700/10 to-transparent',
          highlight: false,
          features: [
              'Projetos Ilimitados',
              'Automações Básicas',
              'Dashboard de Métricas',
              'Anexos (1GB)',
              'Prioridade na fila'
          ]
      },
      {
          id: 'gold',
          label: 'Ouro',
          price: 'R$ 47,90',
          priceId: 'price_gold_789',
          period: '/mês',
          icon: Crown,
          color: 'text-yellow-400',
          borderColor: 'border-yellow-400/50',
          bgGradient: 'from-yellow-400/20 to-transparent',
          highlight: true,
          features: [
              'Tudo do Plano Bronze',
              'IA Generativa (Samuel_IA)',
              'Automações Avançadas',
              'Relatórios em PDF',
              'Gestão de Equipes Completa',
              'Suporte WhatsApp 24/7'
          ]
      }
  ] as const;

  const handlePlanClick = (planId: 'silver' | 'bronze' | 'gold') => {
      setSelectedPlanId(planId);
      setViewState('payment');
  };

  const handleStripeCheckout = async () => {
    if (!selectedPlanId || !stripe) return;
    setProcessingMethod('stripe');

    // Simulação de chamada ao backend para criar sessão do Stripe
    // Em produção: const response = await fetch('/api/create-checkout-session', ...)
    console.log(`Iniciando Checkout Stripe para o plano: ${selectedPlanId}`);

    // Simulando delay de rede
    await new Promise(resolve => setTimeout(resolve, 1500));

    // No mundo real, você redirecionaria:
    // const { error } = await stripe.redirectToCheckout({ sessionId: session.id });

    // Para esta interface, vamos simular o sucesso diretamente após o "processamento"
    await onUpgrade(selectedPlanId);
    setProcessingMethod(null);
    setViewState('plans');
    setSelectedPlanId(null);
  };

  const handleConfirmPayment = async (method: 'pix' | 'card') => {
      if (!selectedPlanId) return;
      setProcessingMethod(method);
      await onUpgrade(selectedPlanId);
      setProcessingMethod(null);
      setTimeout(() => {
          setViewState('plans');
          setSelectedPlanId(null);
      }, 500);
  };

  const handleConfirmCancellation = async () => {
      setIsCancelling(true);
      await onCancelPlan();
      setIsCancelling(false);
      setViewState('plans');
  };

  const handleBack = () => {
      setViewState('plans');
      setSelectedPlanId(null);
  };

  const selectedPlanDetails = PLANS.find(p => p.id === selectedPlanId);

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/80 backdrop-blur-md animate-in fade-in duration-300">
      <div className="w-[90%] max-w-5xl bg-nexus-bg border border-nexus-border rounded-xl shadow-2xl flex flex-col max-h-[90vh] overflow-hidden">

        {/* Header */}
        <div className="p-6 text-center border-b border-nexus-border bg-nexus-card/50 relative">
            {(viewState === 'payment' || viewState === 'cancel_confirmation') && (
                <button 
                    onClick={handleBack}
                    className="absolute left-6 top-6 text-nexus-muted hover:text-nexus-text transition-colors flex items-center gap-1 text-sm"
                >
                    <ArrowLeft size={16} /> Voltar
                </button>
            )}
            <button 
                onClick={onClose} 
                className="absolute right-6 top-6 text-nexus-muted hover:text-nexus-text transition-colors"
            >
                <X size={24} />
            </button>
            <h2 className="text-2xl font-bold text-nexus-text mb-2 flex items-center justify-center gap-2">
                <Rocket className="text-nexus-cobalt" /> Evolua seu Workflow
            </h2>
            <p className="text-nexus-muted">
                {viewState === 'plans' && 'Escolha o plano ideal para escalar a gestão dos seus projetos.'}
                {viewState === 'payment' && 'Pagamento seguro processado via Stripe.'}
                {viewState === 'cancel_confirmation' && 'Gerenciamento de Assinatura'}
            </p>
        </div>

        {/* Content Area */}
        <div className="p-8 overflow-y-auto bg-nexus-bg custom-scrollbar flex-1">

            {viewState === 'plans' && (
                <>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        {PLANS.map((plan) => {
                            const isCurrent = currentUser.plan === plan.id;
                            return (
                                <div 
                                    key={plan.id}
                                    className={`
                                        relative rounded-xl border p-6 flex flex-col transition-all duration-300 group
                                        ${plan.borderColor} bg-gradient-to-b ${plan.bgGradient}
                                        hover:translate-y-[-5px] hover:shadow-xl
                                        ${plan.highlight ? 'ring-1 ring-yellow-400/30' : ''}
                                    `}
                                >
                                    {plan.highlight && (
                                        <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-yellow-400 text-black text-[10px] font-bold px-3 py-1 rounded-full uppercase tracking-widest shadow-lg shadow-yellow-400/20">
                                            Mais Popular
                                        </div>
                                    )}

                                    <div className="flex items-center gap-3 mb-4">
                                        <div className={`p-2 rounded-lg bg-nexus-bg border border-nexus-border ${plan.color}`}>
                                            <plan.icon size={24} />
                                        </div>
                                        <h3 className={`text-xl font-bold ${plan.color}`}>{plan.label}</h3>
                                    </div>

                                    <div className="mb-6">
                                        <span className="text-3xl font-bold text-nexus-text">{plan.price}</span>
                                        <span className="text-sm text-nexus-muted">{plan.period}</span>
                                    </div>

                                    <ul className="space-y-3 mb-8 flex-1">
                                        {plan.features.map((feat, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-nexus-muted group-hover:text-nexus-text transition-colors">
                                                <Check size={16} className={`mt-0.5 ${plan.color}`} />
                                                <span className="leading-tight">{feat}</span>
                                            </li>
                                        ))}
                                    </ul>

                                    <button
                                        disabled={isCurrent}
                                        onClick={() => handlePlanClick(plan.id)}
                                        className={`
                                            w-full py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 transition-all
                                            ${isCurrent 
                                                ? 'bg-nexus-card text-nexus-muted cursor-default border border-nexus-border' 
                                                : plan.highlight 
                                                    ? 'bg-yellow-400 text-black hover:bg-yellow-500 shadow-lg shadow-yellow-400/20' 
                                                    : 'bg-nexus-cobalt text-white hover:bg-blue-600 shadow-lg shadow-blue-900/20'}
                                            disabled:opacity-70 disabled:cursor-not-allowed
                                        `}
                                    >
                                        {isCurrent ? (
                                            <>Plano Atual</>
                                        ) : (
                                            <>
                                                Assinar {plan.label}
                                            </>
                                        )}
                                    </button>

                                    {isCurrent && currentUser.plan !== 'free' && (
                                        <button 
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setViewState('cancel_confirmation');
                                            }}
                                            className="w-full mt-3 py-2 text-xs font-medium text-red-500 hover:text-red-600 hover:bg-red-500/10 rounded transition-colors border border-transparent hover:border-red-500/20"
                                        >
                                            Cancelar Assinatura
                                        </button>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                    <div className="mt-8 flex flex-col items-center gap-3">
                        <div className="flex items-center gap-4 opacity-50">
                             <img src="https://upload.wikimedia.org/wikipedia/commons/b/ba/Stripe_Logo%2C_revised_2016.svg" alt="Stripe" className="h-6 filter grayscale brightness-200" />
                             <div className="h-4 w-px bg-nexus-border"></div>
                             <div className="flex items-center gap-1 text-[10px] text-nexus-muted uppercase tracking-widest">
                                <Shield size={12} /> Pagamentos Seguros
                             </div>
                        </div>
                    </div>
                </>
            )}

            {viewState === 'payment' && (
                <div className="max-w-2xl mx-auto animate-in slide-in-from-right-8 duration-300">

                    <div className={`mb-8 p-6 rounded-xl border bg-gradient-to-r ${selectedPlanDetails?.bgGradient} ${selectedPlanDetails?.borderColor} flex items-center justify-between`}>
                        <div className="flex items-center gap-4">
                            <div className={`p-3 rounded-lg bg-nexus-bg border border-nexus-border ${selectedPlanDetails?.color}`}>
                                {selectedPlanDetails && <selectedPlanDetails.icon size={32} />}
                            </div>
                            <div>
                                <p className="text-sm text-nexus-muted uppercase tracking-wider font-bold">Resumo do Pedido</p>
                                <h3 className="text-2xl font-bold text-nexus-text">Plano {selectedPlanDetails?.label}</h3>
                            </div>
                        </div>
                        <div className="text-right">
                             <div className="text-3xl font-bold text-nexus-text">{selectedPlanDetails?.price}</div>
                             <div className="text-xs text-nexus-muted">Cobrado mensalmente</div>
                        </div>
                    </div>

                    <h3 className="text-lg font-bold text-nexus-text mb-4 flex items-center gap-2">
                        <Lock size={18} className="text-nexus-cobalt" /> Finalizar Pagamento
                    </h3>

                    <div className="grid grid-cols-1 gap-4">
                        {/* STRIPE CHECKOUT OPTION (PRIMARY) */}
                        <button 
                            onClick={handleStripeCheckout}
                            disabled={processingMethod !== null}
                            className={`
                                relative group p-5 rounded-lg border border-nexus-cobalt/30 bg-nexus-card hover:border-nexus-cobalt hover:bg-nexus-cobalt/5 transition-all text-left flex items-center gap-4
                                ${processingMethod === 'stripe' ? 'border-nexus-cobalt bg-nexus-cobalt/5' : ''}
                            `}
                        >
                            <div className="w-12 h-12 rounded-full bg-nexus-cobalt/20 border border-nexus-cobalt/30 flex items-center justify-center text-nexus-cobalt group-hover:scale-110 transition-transform">
                                {processingMethod === 'stripe' ? <Loader2 className="animate-spin" /> : <ShieldCheck size={24} />}
                            </div>
                            <div className="flex-1">
                                <h4 className="font-bold text-nexus-text text-lg flex items-center gap-2">
                                    Checkout Seguro Stripe
                                    <span className="text-[10px] bg-nexus-cobalt/20 text-nexus-cobalt px-2 py-0.5 rounded uppercase tracking-wide">Recomendado</span>
                                </h4>
                                <p className="text-sm text-nexus-muted">Pague com Cartão de Crédito ou Google Pay através da infraestrutura global da Stripe.</p>
                            </div>
                             <div className="w-6 h-6 rounded-full border-2 border-nexus-border group-hover:border-nexus-cobalt flex items-center justify-center">
                                <div className={`w-3 h-3 rounded-full bg-nexus-cobalt transition-transform ${processingMethod === 'stripe' ? 'scale-100' : 'scale-0'}`}></div>
                            </div>
                        </button>

                        <div className="flex items-center gap-4 py-2">
                            <div className="flex-1 h-px bg-nexus-border"></div>
                            <span className="text-[10px] font-bold text-nexus-muted uppercase tracking-widest">Alternativas</span>
                            <div className="flex-1 h-px bg-nexus-border"></div>
                        </div>

                        {/* PIX OPTION */}
                        <button 
                            onClick={() => handleConfirmPayment('pix')}
                            disabled={processingMethod !== null}
                            className={`
                                relative group p-4 rounded-lg border border-nexus-border bg-nexus-card hover:border-green-500 transition-all text-left flex items-center gap-4
                                ${processingMethod === 'pix' ? 'border-green-500 bg-green-500/5' : ''}
                            `}
                        >
                            <div className="w-10 h-10 rounded-full bg-nexus-bg border border-nexus-border flex items-center justify-center text-green-500 group-hover:scale-110 transition-transform">
                                {processingMethod === 'pix' ? <Loader2 className="animate-spin" size={16} /> : <QrCode size={18} />}
                            </div>
                            <div className="flex-1">
                                <h4 className="font-bold text-nexus-text text-sm flex items-center gap-2">
                                    Pix Estático
                                </h4>
                                <p className="text-xs text-nexus-muted">Geração de QR Code manual para liberação assistida.</p>
                            </div>
                        </button>
                    </div>

                    <div className="mt-8 flex items-center justify-center gap-2 text-[10px] text-nexus-muted opacity-50 uppercase tracking-widest">
                        <Lock size={10} /> Conexão Criptografada SSL
                    </div>
                </div>
            )}

            {viewState === 'cancel_confirmation' && (
                <div className="max-w-md mx-auto animate-in fade-in zoom-in-95 duration-200 text-center py-8">
                    <div className="w-20 h-20 bg-red-500/10 rounded-full flex items-center justify-center mx-auto mb-6 text-red-500 border border-red-500/20">
                        <AlertCircle size={40} />
                    </div>
                    <h3 className="text-2xl font-bold text-nexus-text mb-3">Cancelar Assinatura?</h3>
                    <p className="text-nexus-muted mb-8 text-sm leading-relaxed">
                        Ao confirmar, você perderá acesso aos recursos exclusivos do plano <strong>{currentUser.plan?.toUpperCase()}</strong> e retornará ao plano Gratuito. Suas faturas recorrentes no Stripe serão interrompidas imediatamente.
                    </p>

                    <div className="space-y-3">
                        <button 
                            onClick={handleConfirmCancellation}
                            disabled={isCancelling}
                            className="w-full py-3 bg-red-500 hover:bg-red-600 text-white font-bold rounded-lg transition-colors shadow-lg shadow-red-500/20 flex items-center justify-center gap-2 disabled:opacity-50"
                        >
                            {isCancelling ? <Loader2 className="animate-spin" /> : <><X size={18} /> Confirmar Cancelamento</>}
                        </button>
                        <button 
                            onClick={() => setViewState('plans')}
                            disabled={isCancelling}
                            className="w-full py-3 bg-transparent hover:bg-nexus-card border border-transparent hover:border-nexus-border text-nexus-muted hover:text-nexus-text font-medium rounded-lg transition-colors"
                        >
                            Não, quero manter minha assinatura
                        </button>
                    </div>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import { Task, Project } from '../types';
import { BarChart3, PieChart, TrendingUp, CheckCircle, AlertCircle, Clock, Filter, LayoutGrid, BrainCircuit, Tag, ArrowRight, Activity, Zap, Target } from 'lucide-react';
import { STATUS_COLUMNS } from '../constants';

interface MonitoringDashboardProps {
  tasks: Task[]; // All tasks available to the user
  projects: Project[]; // All projects available to the user
  initialProjectId?: string | null;
}

interface PatternGroup {
    id: string;
    label: string;
    reason: string;
    tasks: Task[];
    icon: React.ElementType;
    colorClass: string;
}

export const MonitoringDashboard: React.FC<MonitoringDashboardProps> = ({ tasks, projects, initialProjectId }) => {
  const [selectedProjectId, setSelectedProjectId] = useState<string>('all');

  useEffect(() => {
    if (initialProjectId) {
        setSelectedProjectId(initialProjectId);
    } else {
        setSelectedProjectId('all');
    }
  }, [initialProjectId]);

  const filteredTasks = useMemo(() => {
      if (selectedProjectId === 'all') return tasks;
      return tasks.filter(t => t.projectId === selectedProjectId);
  }, [tasks, selectedProjectId]);

  const currentProject = projects.find(p => p.id === selectedProjectId);

  const stats = useMemo(() => {
    const total = filteredTasks.length;
    const done = filteredTasks.filter(t => t.status === 'done').length;
    const inProgress = filteredTasks.filter(t => t.status === 'inprogress').length;
    const backlog = filteredTasks.filter(t => t.status === 'backlog').length;
    const review = filteredTasks.filter(t => t.status === 'review').length;

    const completionRate = total === 0 ? 0 : Math.round((done / total) * 100);

    // Priority Distribution
    const high = filteredTasks.filter(t => t.priority === 'High').length;
    const medium = filteredTasks.filter(t => t.priority === 'Medium').length;
    const low = filteredTasks.filter(t => t.priority === 'Low').length;

    // Health Score Algorithm
    // Based on High Priority Pendings vs Completion
    const highPriorityPending = filteredTasks.filter(t => t.priority === 'High' && t.status !== 'done').length;
    const healthScore = Math.max(0, Math.min(100, (completionRate * 1.2) - (highPriorityPending * 5)));

    return { total, done, inProgress, backlog, review, completionRate, high, medium, low, healthScore };
  }, [filteredTasks]);

  const statusCounts = STATUS_COLUMNS.map(col => ({
    label: col.label,
    count: filteredTasks.filter(t => t.status === col.id).length,
    percent: filteredTasks.length ? (filteredTasks.filter(t => t.status === col.id).length / filteredTasks.length) * 100 : 0
  }));

  const patternGroups = useMemo(() => {
    const groups: PatternGroup[] = [];
    const activeTasks = filteredTasks.filter(t => t.status !== 'done');

    const highPri = activeTasks.filter(t => t.priority === 'High');
    if (highPri.length >= 2) {
        groups.push({
            id: 'critical-focus',
            label: 'Foco Crítico',
            reason: `Detectadas ${highPri.length} tarefas de alta prioridade pendentes.`,
            tasks: highPri,
            icon: AlertCircle,
            colorClass: 'text-red-500 border-red-500/20 bg-red-500/5'
        });
    }

    const tagMap = new Map<string, Task[]>();
    activeTasks.forEach(t => {
        t.tags.forEach(tag => {
            if (!tagMap.has(tag.text)) tagMap.set(tag.text, []);
            tagMap.get(tag.text)?.push(t);
        });
    });

    tagMap.forEach((grpTasks, tag) => {
        if (grpTasks.length >= 3) {
             groups.push({
                id: `cluster-${tag}`,
                label: `Cluster: ${tag}`,
                reason: `Agrupamento temático identificado (${grpTasks.length} itens).`,
                tasks: grpTasks,
                icon: Tag,
                colorClass: 'text-nexus-cobalt border-nexus-cobalt/20 bg-nexus-cobalt/5'
            });
        }
    });

    const stalled = activeTasks.filter(t => t.status === 'inprogress' && t.progress < 25);
    if (stalled.length >= 2) {
         groups.push({
            id: 'stalled',
            label: 'Possível Gargalo',
            reason: 'Tarefas em progresso inicial (<25%) indicam possível bloqueio.',
            tasks: stalled,
            icon: Clock,
            colorClass: 'text-orange-500 border-orange-500/20 bg-orange-500/5'
        });
    }

    return groups;
  }, [filteredTasks]);

  if (projects.length === 0) {
    return (
        <div className="flex-1 flex flex-col items-center justify-center text-nexus-muted">
            <BarChart3 size={48} className="mb-4 opacity-50" />
            <p>Nenhum projeto encontrado.</p>
        </div>
    )
  }

  return (
    <div className="flex-1 p-8 overflow-y-auto bg-nexus-bg space-y-8">
      {/* Header Analytical Section */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-nexus-border pb-6">
        <div className="space-y-1">
            <div className="flex items-center gap-2 text-[10px] font-bold text-nexus-cobalt uppercase tracking-[0.2em]">
                <Activity size={12} /> Engenharia de Dados & Métricas
            </div>
            <h2 className="text-3xl font-bold text-nexus-text tracking-tight flex items-center gap-3">
                Monitoramento: 
                <span className="text-nexus-muted font-normal">
                    {selectedProjectId === 'all' ? 'Relatório Consolidado' : currentProject?.name}
                </span>
            </h2>
        </div>

        <div className="flex items-center gap-3 bg-nexus-card border border-nexus-border rounded-md px-3 py-2 shadow-sm min-w-[280px]">
            <Filter size={14} className="text-nexus-muted" />
            <div className="flex-1">
                <select 
                    value={selectedProjectId}
                    onChange={(e) => setSelectedProjectId(e.target.value)}
                    className="w-full bg-transparent text-xs font-bold text-nexus-text outline-none cursor-pointer uppercase tracking-wider"
                >
                    <option value="all">TODOS OS PROJETOS</option>
                    {projects.map(p => (
                        <option key={p.id} value={p.id}>{p.name.toUpperCase()}</option>
                    ))}
                </select>
            </div>
        </div>
      </div>

      {/* Primary Analytical Widgets */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {/* Project Health Score */}
        <div className="md:col-span-2 bg-nexus-card border border-nexus-border p-6 rounded-lg flex items-center justify-between group hover:border-nexus-cobalt transition-colors">
            <div className="space-y-4 flex-1">
                <div className="flex items-center gap-2">
                    <Target size={18} className="text-nexus-cobalt" />
                    <h3 className="text-xs font-bold text-nexus-muted uppercase tracking-widest">Health Score</h3>
                </div>
                <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-mono font-bold text-nexus-text tracking-tighter">{Math.round(stats.healthScore)}</span>
                    <span className="text-sm text-nexus-muted font-mono">/100</span>
                </div>
                <p className="text-[10px] text-nexus-muted leading-relaxed max-w-[200px]">
                    Índice calculado com base na vazão de tarefas vs. tickets de alta prioridade.
                </p>
            </div>
            <div className="relative w-24 h-24">
                <svg className="w-full h-full transform -rotate-90">
                    <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-nexus-border" />
                    <circle cx="48" cy="48" r="40" stroke="currentColor" strokeWidth="8" fill="transparent" 
                        strokeDasharray={251.2}
                        strokeDashoffset={251.2 - (251.2 * stats.healthScore) / 100}
                        className="text-nexus-cobalt transition-all duration-1000"
                    />
                </svg>
                <div className="absolute inset-0 flex items-center justify-center">
                    <Activity size={24} className="text-nexus-cobalt animate-pulse" />
                </div>
            </div>
        </div>

        {/* Rapid Metrics */}
        <div className="bg-nexus-card border border-nexus-border p-6 rounded-lg space-y-4">
            <div className="flex items-center gap-2">
                <Zap size={16} className="text-nexus-accent" />
