        try {
          const stripeInstance = window.Stripe('pk_test_TYooMQauvdEDq54NiTphI7jx');
          setStripe(stripeInstance);
        } catch (err) {
          console.error("Erro ao inicializar Stripe:", err);
          setStripeError("Falha ao carregar o provedor de pagamentos.");
