                                        <li key={i} className="flex items-start gap-2 text-sm text-nexus-muted group-hover:text-nexus-text transition-colors">
                                            <Check size={16} className={`mt-0.5 ${plan.color}`} />
                                            <span className="leading-tight">{feat}</span>
                                        </li>
