                                </ul>

                                <button
                                    disabled={isCurrent}
                                    onClick={() => handlePlanClick(plan.id)}
                                    className={`
                                        w-full py-3 rounded-lg font-bold text-sm flex items-center justify-center gap-2 transition-all
                                        ${isCurrent 
